def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda x: sum(v == x for row in grid for v in row))
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and
                            p not in seen and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        stack.append(p)
            comps.append((color, cells))

    # Find the most prominent component shaped like two perpendicular straight arms.
    source = None
    for color, cells in comps:
        cellset = set(cells)
        best = None
        for r, c in cells:
            for dr in (-1, 1):
                for dc in (-1, 1):
                    vr = 1
                    while (r + dr * vr, c) in cellset:
                        vr += 1
                    hc = 1
                    while (r, c + dc * hc) in cellset:
                        hc += 1
                    union = vr + hc - 1
                    coverage = union / len(cells)
                    if vr >= 3 and hc >= 3 and coverage >= 0.7:
                        score = (vr + hc, coverage)
                        if best is None or score > best[0]:
                            best = (score, (r, c), dr, dc)
        if best:
            candidate = (best[0], color, cells, best[1], best[2], best[3])
            if source is None or candidate[0] > source[0]:
                source = candidate

    if source is None:
        return [row[:] for row in grid]

    _, source_color, source_cells, (cr, cc), arm_r, arm_c = source
    missing_r, missing_c = -arm_r, -arm_c
    target = None
    best_dist = None

    for color, cells in comps:
        if color == source_color and set(cells) == set(source_cells):
            continue
        mr = sum(r for r, c in cells) / len(cells)
        mc = sum(c for r, c in cells) / len(cells)
        dr, dc = mr - cr, mc - cc
        # Keep objects lying generally in the quadrant opposite the L's arms.
        if dr * missing_r + dc * missing_c <= 0:
            continue
        dist = (dr * dr + dc * dc) ** 0.5
        if best_dist is None or dist < best_dist:
            best_dist = dist
            target = cells

    out = [row[:] for row in grid]
    if target:
        for r, c in target:
            out[r][c] = source_color
    return out
